const src = $input.first().json || {};
const body = (src.body && typeof src.body === 'object') ? src.body : {};
const q = Object.assign({}, src.query || {}, body);
const mode = String(q.mode || 'quotes').toLowerCase();
if (mode === 'search') {
  const term = String(q.q || '').trim().slice(0, 60);
  if (!term) return [{ json: { kind: 'none', mode: mode } }];
  return [{ json: { kind: 'search', mode: mode, url: 'https://query1.finance.yahoo.com/v1/finance/search?q=' + encodeURIComponent(term) + '&quotesCount=10&newsCount=0&listsCount=0&enableFuzzyQuery=true' } }];
}
const RANGES = { '1d': '5m', '5d': '15m', '1mo': '1d', '3mo': '1d', '6mo': '1d', 'ytd': '1d', '1y': '1d', '2y': '1wk', '5y': '1wk', 'max': '1mo' };
const from = parseInt(q.from, 10);
const to = parseInt(q.to, 10);
const custom = from > 0 && to > from && (to - from) <= 400 * 86400;
const range = custom ? 'custom' : (RANGES[q.range] ? q.range : '1d');
const interval = custom ? '1d' : RANGES[range];
const span = custom ? ('period1=' + from + '&period2=' + to) : ('range=' + range);
const symbols = String(q.symbols || '').split(',').map(s => s.trim().toUpperCase()).filter(s => /^[A-Z0-9^.=-]{1,20}$/.test(s));
const unique = [...new Set(symbols)].slice(0, 40);
if (!unique.length) return [{ json: { kind: 'none', mode: mode } }];
return unique.map(s => ({ json: { kind: 'chart', mode: mode, symbol: s, range: range, interval: interval, url: 'https://query1.finance.yahoo.com/v8/finance/chart/' + encodeURIComponent(s) + '?' + span + '&interval=' + interval + '&includePrePost=false' } }));

const plans = $('Plan Requests').all();
const responses = $input.all();
const round = (v, d) => (typeof v === 'number' && isFinite(v)) ? Math.round(v * Math.pow(10, d)) / Math.pow(10, d) : null;
const first = plans[0] ? plans[0].json : { mode: 'quotes', kind: 'none' };
const out = { ok: true, mode: first.mode, source: 'Yahoo Finance chart API (unofficial)', generatedAt: new Date().toISOString() };
if (first.kind === 'none') { out.results = []; out.matches = []; return [{ json: out }]; }
if (first.kind === 'search') {
  const sb = responses[0] ? responses[0].json : {};
  const quotes = Array.isArray(sb.quotes) ? sb.quotes : [];
  out.matches = quotes.filter(x => x && x.symbol && x.isYahooFinance !== false).map(x => ({ symbol: x.symbol, name: x.longname || x.shortname || x.symbol, exchange: x.exchDisp || x.exchange || '', type: x.typeDisp || x.quoteType || '' }));
  if (!quotes.length && sb.error) { out.ok = false; out.error = String(sb.error.message || sb.error); }
  return [{ json: out }];
}
out.range = first.range;
out.interval = first.interval;
out.results = plans.map((p, i) => {
  const b = responses[i] ? responses[i].json : null;
  const sym = p.json.symbol;
  const r = b && b.chart && Array.isArray(b.chart.result) ? b.chart.result[0] : null;
  if (!r || !r.meta) {
    let e = 'No data returned';
    if (b && b.chart && b.chart.error) e = b.chart.error.description || b.chart.error.code || e;
    else if (b && b.error) e = b.error.message || String(b.error);
    return { requested: sym, symbol: sym, error: String(e) };
  }
  const m = r.meta;
  const ts = Array.isArray(r.timestamp) ? r.timestamp : [];
  const qd = r.indicators && r.indicators.quote && r.indicators.quote[0] ? r.indicators.quote[0] : {};
  const closes = Array.isArray(qd.close) ? qd.close : [];
  const points = [];
  for (let k = 0; k < ts.length; k++) { const c = closes[k]; if (typeof c === 'number' && isFinite(c)) points.push([ts[k], round(c, 6)]); }
  const reg = m.currentTradingPeriod && m.currentTradingPeriod.regular ? m.currentTradingPeriod.regular : null;
  return {
    requested: sym,
    symbol: m.symbol || sym,
    name: m.longName || m.shortName || m.symbol || sym,
    currency: m.currency || null,
    exchange: m.fullExchangeName || m.exchangeName || '',
    type: m.instrumentType || '',
    price: round(m.regularMarketPrice, 6),
    previousClose: round(m.previousClose, 6),
    chartPreviousClose: round(m.chartPreviousClose, 6),
    dayHigh: round(m.regularMarketDayHigh, 6),
    dayLow: round(m.regularMarketDayLow, 6),
    volume: typeof m.regularMarketVolume === 'number' ? m.regularMarketVolume : null,
    high52: round(m.fiftyTwoWeekHigh, 6),
    low52: round(m.fiftyTwoWeekLow, 6),
    marketTime: m.regularMarketTime || null,
    timezone: m.exchangeTimezoneName || null,
    session: reg ? { start: reg.start, end: reg.end } : null,
    points: points
  };
});
return [{ json: out }];
